int n = 28, m = 4;
if(n % 2 == 0) cout << "CHAN\n";
else cout << "LE\n";

// chia hết cho m
if(n % m == 0) cout << "Chia het\n";
else cout << "Khong chia het\n";

// n là 1 trong 4 số 2, 3, 5, 7
if(n==2 || n==3 || n==5 || n==7) cout << "YES\n";

// năm nhuận
if((n % 400 == 0) || (n % 4 == 0 && n % 100 != 0))
    cout << "YES\n";
else cout << "NO\n";

// lồng nhau: n trong [20,50] và chia hết 2/3/5/7
if(n >= 20 && n <= 50){
    if(n%2==0 || n%3==0 || n%5==0 || n%7==0)
        cout << "YES\n";
    else cout << "NO\n";
}
else cout << "NO\n";

// n có 2 chữ số và chữ số cuối là số nguyên tố
int r = n % 10;
if((n>=10 && n<=99) && (r==2||r==3||r==5||r==7))
    cout << 1 << endl;
else cout << 0 << endl;
